import{_ as s,o as t,c as o,a5 as a}from"./chunks/framework.BPFk9-tb.js";const m=JSON.parse('{"title":"类比宝库工具","description":"","frontmatter":{"date":"2023-05-27T10:56:38","title":"类比宝库工具","categories":["定投人生课堂","定投写作","Mixin机器人"],"tags":["定投人生课堂","定投写作","Mixin机器人"]},"headers":[],"relativePath":"posts/course100/011.md","filePath":"posts/course100/011.md"}'),c={name:"posts/course100/011.md"};function i(p,e,d,r,l,n){return t(),o("div",null,[...e[0]||(e[0]=[a('<p>笑来老师说，每一个类比都是一笔财富。</p><p>对「类比宝库」采用了「定投搜索」一样的命令格式：所有输入将格式化成 <code>/命令 参数</code> (<code>/command args</code> )的格式。</p><p>目前支持的 <code>command</code> 有：</p><ul><li><code>/s</code>，查询包含相关关键字的类比。</li><li><code>/add</code>，添加类比。</li><li><code>/thx</code>，返回感谢列表，感谢列表是不定期更新的。</li></ul><p>当发送的消息不包含命令时，会默认加上 <code>/s</code> 命令，这样可以减少输入，如发送的消息是「时间」时，等同于发送「/s 时间」。</p><p>命令的先后顺序无关，如发送以下消息，效果是一样的：「/s 时间 测试」，「时间 /s 测试」，「时间 测试 /s」。</p><p>如果发送了不支持的命令格式，不会返回任何消息，只会将消息设置为已读状态。</p><p>以下截图：</p><p><img src="https://assets.quill.im/9878sqir61pltenkbdy1kwydgbkh" alt="image.png"><br> 一个的Mixin群的用法，可以自己创建一个群，把「定投搜索」和「类比宝库」都添加到群成员列表里，使用<code>@</code>的方式发消息，此时会收到对应机器人的回复，如下图：</p><p><img src="https://assets.quill.im/0ygidssyawwak5ybgo37tgids5yp" alt="WechatIMG244.png"><br> 战友们可以自行尝试，如果发现工具的问题，可以添加我的微信「Crazy_Airhead」，或Mixin号「1091586」，进行反馈，谢谢。</p>',10)])])}const g=s(c,[["render",i]]);export{m as __pageData,g as default};
